diff --git a/source/connection-record.ts b/source/connection-record.ts
new file mode 100644
index 0000000..c5267c6
--- /dev/null
+++ b/source/connection-record.ts
@@ -0,0 +1,41 @@
+function getExplicitPort(url: URL, address: string): string {
+	if (url.port) {
+		return url.port;
+	}
+
+	// Parse with a different default port so an explicit default isn't discarded.
+	let protocol: string;
+	switch (url.protocol) {
+		case 'http:':
+		case 'ws:': {
+			protocol = 'https:';
+			break;
+		}
+
+		case 'https:':
+		case 'wss:':
+		case 'ftp:': {
+			protocol = 'http:';
+			break;
+		}
+
+		default: {
+			return '';
+		}
+	}
+
+	return new URL(`${protocol}${address.slice(address.indexOf(':') + 1)}`).port;
+}
+
+export function connectionRecord(address: string) {
+	const url = new URL(address);
+	const {hostname, pathname, search, username, password} = url;
+	const port = getExplicitPort(url, address);
+
+	return {
+		hostname: hostname.startsWith('[') ? hostname.slice(1, -1) : hostname,
+		port: port ? Number(port) : null,
+		path: `${pathname}${search}`,
+		auth: username || password ? `${username}:${password}` : null,
+	};
+}
diff --git a/test/connection-record.ts b/test/connection-record.ts
new file mode 100644
index 0000000..97a085f
--- /dev/null
+++ b/test/connection-record.ts
@@ -0,0 +1,36 @@
+import test from 'ava';
+import {connectionRecord} from '../source/connection-record.js';
+
+test('records an IPv6 hostname, port, path and escaped credentials', t => {
+	t.deepEqual(connectionRecord('https://user%40example:p%3Ass@[2001:db8::1]:8443/a%20b?q=a%23b#fragment'), {
+		hostname: '2001:db8::1',
+		port: 8443,
+		path: '/a%20b?q=a%23b',
+		auth: 'user%40example:p%3Ass',
+	});
+});
+
+test('preserves explicit default ports and port zero', t => {
+	t.is(connectionRecord('http://example.com:00080/').port, 80);
+	t.is(connectionRecord('https://example.com:443/').port, 443);
+	t.is(connectionRecord('https://example.com:0/').port, 0);
+});
+
+test('uses null for absent port and credentials', t => {
+	t.deepEqual(connectionRecord('https://example.com#fragment'), {
+		hostname: 'example.com',
+		port: null,
+		path: '/',
+		auth: null,
+	});
+});
+
+test('joins credentials with a colon when either component is present', t => {
+	t.is(connectionRecord('https://user@example.com/').auth, 'user:');
+	t.is(connectionRecord('https://:password@example.com/').auth, ':password');
+});
+
+test('rejects relative and invalid URLs', t => {
+	t.throws(() => connectionRecord('/relative'), {instanceOf: TypeError});
+	t.throws(() => connectionRecord('https://example.com:65536/'), {instanceOf: TypeError});
+});
